import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, uniform, positionLocal } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-title';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 3.2;
  const height = 2.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imgTex = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  imgTex.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const texColor = texture(imgTex, uvNode);

  // engineered gradient overlay: ink -> surface, subtle vertical gradient
  const inkColor = uniform(new THREE.Color(0x16161d));
  const surfaceColor = uniform(new THREE.Color(0x0b0b10));
  const gradFactor = uvNode.y;
  const gradientColor = mix(surfaceColor, inkColor, gradFactor);

  // grain via simple hash based on position (static, no time dependency)
  const grainSeed = uvNode.x.mul(1234.5).add(uvNode.y.mul(789.1));
  const grain = grainSeed.sin().mul(43758.5453).fract().mul(0.04).sub(0.02);

  const finalColor = texColor.rgb.mul(0.7).add(gradientColor.mul(0.3)).add(grain);
  material.colorNode = vec4(finalColor, texColor.a);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'hub-collection-title-plane';
  group.add(plane);

  // Headline text: "Collection"
  const textMesh = createTextMesh(ctx.fontAtlas, {
    text: 'Collection',
    font: 'Lora',
    weight: 400,
    sizeEm: 0.34,
    color: '#e8ecf2',
    align: 'center',
    anchor: 'center'
  });
  textMesh.name = 'hub-collection-title-text';
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (imgTex && imgTex.dispose) imgTex.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
